def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_c = 0
    for h in history:
        if h[1] == 'C':
            opp_c += 1
    opp_d = n - opp_c

    my_last, opp_last = history[-1]

    recent = history[-5:] if n >= 5 else history
    exploit_count = 0
    for h in recent:
        if h[0] == 'D' and h[1] == 'C':
            exploit_count += 1
    if exploit_count >= 2:
        return 'D'

    if opp_d == 0:
        if n >= 5:
            has_d = False
            for h in history[-3:]:
                if h[0] == 'D':
                    has_d = True
                    break
            if not has_d:
                return 'D'
        if n >= 2 and history[-2][0] == 'D' and my_last == 'C' and opp_last == 'C':
            return 'D'
        return 'C'

    if opp_last == 'D':
        if my_last == 'D':
            if opp_d > opp_c:
                return 'D'
            return 'C'
        else:
            if n >= 2 and history[-2][1] == 'D':
                return 'D'
            if opp_d > opp_c:
                return 'D'
            return 'C'

    if my_last == 'D' and opp_last == 'C':
        return 'D'

    if opp_last == 'C' and my_last == 'C':
        if n >= 10 and n < 95:
            recent_opp_d = False
            for h in history[-10:]:
                if h[1] == 'D':
                    recent_opp_d = True
                    break
            recent_my_d = False
            for h in history[-5:]:
                if h[0] == 'D':
                    recent_my_d = True
                    break
            if not recent_opp_d and not recent_my_d:
                return 'D'
        if n >= 99:
            return 'D'
        return 'C'

    return 'C'
